SELECT Q6J, Q6I, Q6H, Q6G, Q6F, Q6E, Q6D, Q6C, Q6B, Q6A, Q5J, Q5I, Q5H, Q5G, Q5F, Q4D, Q4C, Q4B, Q4A, Q3H, Q3G, Q3F, Q3E, Q3D, Q3C, Q3B, Q3A, Q2I, Q2H, Q2G, Q2F, Q2E 
FROM response_post 
INNER JOIN voter_info ON response_post.ID = voter_info.ID 
WHERE voter_info.CONDITION = 1 AND COALESCE(Q6J, Q6I, Q6H, Q6G, Q6F, Q6E, Q6D,  Q5B, Q5A, Q4J, Q4I, Q4H, Q4G, Q4F, Q4E, Q4D, Q4C, Q4B, Q4A, Q3H, Q3G, Q3F, Q3E, Q3B, Q2A, Q1 ) is not Null ;    